"use strict";(function(){let showSpinner=!1;window.onbeforeunload=function(){if(!showSpinner)return;RockSortable.showSpinner()};window.addEventListener("click",(e)=>{let button=e.target.closest(".ui-dialog-buttonset button");if(!button)return;showSpinner=!0})})();function _RockSortable(){this.enabled=localStorage.getItem("rpb-sortable-disabled")==="1"?!1:!0;this.sortables=[]}
_RockSortable.prototype.disable=function(){this.enabled=!1;let body=document.querySelector("body");this.sortables.forEach((sortable)=>{sortable.option("disabled",!0)});localStorage.setItem("rpb-sortable-disabled",1);body.classList.add("no-sortable");body.classList.remove("is-sortable")};_RockSortable.prototype.enable=function(){this.enabled=!0;let body=document.querySelector("body");this.sortables.forEach((sortable)=>{sortable.option("disabled",!1)});localStorage.setItem("rpb-sortable-disabled",0);body.classList.remove("no-sortable");body.classList.add("is-sortable")};_RockSortable.prototype.getContainer=function(el){return el.closest("[sortable]")||!1};_RockSortable.prototype.getPageId=function(el){let id=el.getAttribute("data-rpbblock");if(id)return id;return el.querySelector("[data-rpbblock]").getAttribute("data-rpbblock")};_RockSortable.prototype.getPageIds=function(el){let container=this.getContainer(el);let blocks=container.querySelectorAll("[data-rpbblock]");let ids=[];blocks.forEach((block)=>{ids.push(this.getPageId(block))});return ids};_RockSortable.prototype.parseAttributes=function(el){const result={};const attribute="sortable";el=this.getContainer(el);if(el.hasAttribute(attribute)){const attributeValue=el.getAttribute(attribute).replace(/;+\s*$/,"");const pairs=attributeValue.split(";").map((pair)=>pair.trim());pairs.forEach((pair)=>{const[key,value]=pair.split(":").map((item)=>item.trim());result[key]=value})}
return result};_RockSortable.prototype.saveSort=function(el){let url=RockFrontend.rootUrl+"rockpagebuilder-savesort?block="+this.getPageId(el)+"&sort="+this.getPageIds(el).join("|");fetch(url).then((response)=>{if(response.ok){let settings=this.parseAttributes(el);if(settings.reload){this.showSpinner();document.location.reload(!0)}
return response.json()}
throw new Error("Something went wrong")}).then((responseJson)=>{}).catch((error)=>{console.error(error)})};_RockSortable.prototype.showSpinner=function(){document.querySelector("body").classList.add("rpb-reloading");let div=document.createElement("div");div.id="rpb-reloading";div.innerHTML='<span class="loader"></span>';document.body.appendChild(div);setTimeout(()=>{div.classList.add("show")},10)};_RockSortable.prototype.toggle=function(){if(this.enabled)this.disable();else this.enable()};var RockSortable=new _RockSortable();function makeSortable(){let containers=document.querySelectorAll("[sortable]");let body=document.querySelector("body");let beforeSort=!1;if(!RockSortable.enabled)body.classList.add("no-sortable");else body.classList.add("is-sortable");containers.forEach((container)=>{if(container.hasAttribute("data-sortable-init"))return;container.setAttribute("data-sortable-init",!0);let removeNoAlfred=!0;let s=new Sortable(container,{animation:150,disabled:!RockSortable.enabled,filter:".alfredelements",forceFallback:!0,onChoose:(e)=>{document.body.classList.add("grabbing");beforeSort=RockSortable.getPageIds(e.item).join(",");if(body.classList.contains("no-alfred")){removeNoAlfred=!1}else{body.classList.add("no-alfred");removeNoAlfred=!0}},onEnd:(e)=>{if(removeNoAlfred)body.classList.remove("no-alfred");if(RockSortable.getPageIds(e.item).join(",")==beforeSort)return;RockSortable.saveSort(e.item)},onUnchoose:(e)=>{document.body.classList.remove("grabbing");if(removeNoAlfred)body.classList.remove("no-alfred");},});RockSortable.sortables.push(s)})}
document.addEventListener("DOMContentLoaded",makeSortable);document.addEventListener("keyup",function(event){if(event.key==="Shift")RockSortable.toggle();});document.addEventListener("DOMContentLoaded",function(){document.body.classList.add("rpb-active")})